(()=>{const localized=()=>{const hans=document.documentElement.lang==='zh-Hans'||new URLSearchParams(location.search).get('lang')==='zh-Hans';return hans?{title:'最新文章',expand:'展开全部文章',note:'精选文章；可在本专区展开浏览完整文章。'}:{title:'最新文章',expand:'展開全部文章',note:'精選文章；可在本專區展開瀏覽完整文章。'}};const apply=()=>{const root=document.querySelector('#home-latest-25-20261118');if(!root)return;const copy=localized();const heading=root.querySelector('h2');if(heading)heading.textContent=copy.title;root.querySelectorAll('button').forEach(button=>{if(/(?:展開|展开).*25/.test(button.textContent))button.textContent=copy.expand});root.querySelectorAll('p').forEach(p=>{if(/(?:完整|完整).*25|25.*(?:篇|篇)/.test(p.textContent))p.textContent=copy.note});};addEventListener('load',()=>{apply();setTimeout(apply,1200);setTimeout(apply,3000)},{once:true});})();